use vstd::prelude::*;

verus! {

fn reverse(a: &Vec<i32>) -> (a_rev: Vec<i32>)
    ensures
        a_rev.len() == a.len(),
        forall|i: int| 0 <= i < a.len() ==> a_rev[i] == a[(a.len() - 1 - i) as int],
{
    let n = a.len();
    let mut a_rev = Vec::with_capacity(n);

    for i in (0..n).rev()
        invariant
            a_rev.len() == n - (i + 1),
            forall|k: int|
                0 <= k < a_rev.len()
                ==> a_rev[k] == a[(n - 1 - k) as int],
        decreases i,
    {
        a_rev.push(a[i]);

        assert(a_rev.len() == n - i);
        assert(forall|k: int|
            0 <= k < a_rev.len()
            ==> a_rev[k] == a[(n - 1 - k) as int]
        ) by {
            // For k < old_len, follows from loop invariant.
            // For k == old_len, it's exactly the element we just pushed: a[i],
            // and old_len == n - (i + 1) so n - 1 - old_len == i.
        };
    }

    a_rev
}

} // verus!

